import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaExclamationCircle, FaCamera, FaLocationArrow, FaTag, FaFunnel, FaPaperPlane } from 'react-icons/fa';

function IssueReport() {
  const [user] = useState(() => {
    const stored = localStorage.getItem('user');
    return stored ? JSON.parse(stored) : null;
  });

  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    description: '',
    category: '',
    location: '',
    priority: 'Medium',
    images: []
  });

  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const categories = [
    'Furniture',
    'Electrical',
    'Plumbing',
    'Sanitation',
    'Classroom',
    'Playground',
    'Laboratory',
    'Other'
  ];

  const priorities = ['Low', 'Medium', 'High', 'Critical'];

  const locations = [
    'Room 101',
    'Room 102',
    'Room 201',
    'Library',
    'Laboratory',
    'Toilet Block A',
    'Toilet Block B',
    'Playground',
    'Main Entrance',
    'Cafeteria',
    'Office'
  ];

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleImageUpload = (e) => {
    const files = Array.from(e.target.files);
    setFormData({
      ...formData,
      images: files
    });
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.description.trim()) newErrors.description = 'Description is required';
    else if (formData.description.length < 10) newErrors.description = 'Description must be at least 10 characters';
    if (!formData.category) newErrors.category = 'Category is required';
    if (!formData.location) newErrors.location = 'Location is required';
    if (!formData.priority) newErrors.priority = 'Priority is required';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    // Create new issue
    const newIssue = {
      id: Date.now(),
      ...formData,
      status: 'Pending',
      reportedBy: user?.name || 'Unknown',
      reportedDate: new Date().toISOString().split('T')[0],
      timeline: [{
        action: 'Issue Reported',
        time: new Date().toLocaleString()
      }]
    };

    // Store in localStorage (replace with API call)
    const existingIssues = JSON.parse(localStorage.getItem('issues') || '[]');
    localStorage.setItem('issues', JSON.stringify([...existingIssues, newIssue]));

    setSubmitted(true);

    // Redirect to tracking after 2 seconds
    setTimeout(() => {
      navigate('/track-issues');
    }, 2000);
  };

  if (!user) {
    return (
      <div className="py-5 text-center">
        <div className="alert alert-warning">
          Please login to report issues
        </div>
        <Link to="/login" className="btn btn-custom">Go to Login</Link>
      </div>
    );
  }

  if (submitted) {
    return (
      <div className="py-5">
        <div className="container">
          <div className="row justify-content-center">
            <div className="col-md-6 text-center">
              <div className="card-custom">
                <div className="card-body p-5">
                  <FaCheckCircle className="mb-3" style={{ fontSize: '4rem', color: '#198754' }} />
                  <h3>Issue Reported Successfully!</h3>
                  <p className="text-muted">Your issue has been submitted and is now being reviewed.</p>
                  <Link to="/track-issues" className="btn btn-custom">
                    <FaList className="me-2" /> Track Your Issue
                  </Link>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="py-5">
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-8 col-lg-7">
            <div className="card-custom">
              <div className="card-header">
                <h3><FaExclamationCircle className="me-2" /> Report Facility Issue</h3>
                <p className="mb-0">Help us maintain a safe school environment</p>
              </div>
              <div className="card-body p-4">
                <form onSubmit={handleSubmit}>
                  <div className="mb-4">
                    <label className="form-label">
                      <FaExclamationCircle className="me-2" /> Issue Description
                    </label>
                    <textarea
                      name="description"
                      className="form-control form-control-lg"
                      rows="4"
                      placeholder="Describe the issue in detail (e.g., broken chair, leaking toilet, flickering light)"
                      value={formData.description}
                      onChange={handleChange}
                    />
                    {errors.description && <div className="text-danger small mt-1">{errors.description}</div>}
                  </div>

                  <div className="row">
                    <div className="col-md-6 mb-3">
                      <label className="form-label">
                        <FaTag className="me-2" /> Category
                      </label>
                      <select
                        name="category"
                        className="form-select form-select-lg"
                        value={formData.category}
                        onChange={handleChange}
                      >
                        <option value="">Select Category</option>
                        {categories.map(cat => (
                          <option key={cat} value={cat}>{cat}</option>
                        ))}
                      </select>
                      {errors.category && <div className="text-danger small mt-1">{errors.category}</div>}
                    </div>

                    <div className="col-md-6 mb-3">
                      <label className="form-label">
                        <FaFunnel className="me-2" /> Priority Level
                      </label>
                      <select
                        name="priority"
                        className="form-select form-select-lg"
                        value={formData.priority}
                        onChange={handleChange}
                      >
                        {priorities.map(p => (
                          <option key={p} value={p}>{p}</option>
                        ))}
                      </select>
                      {errors.priority && <div className="text-danger small mt-1">{errors.priority}</div>}
                    </div>
                  </div>

                  <div className="mb-4">
                    <label className="form-label">
                      <FaLocationArrow className="me-2" /> Location
                    </label>
                    <select
                      name="location"
                      className="form-select form-select-lg"
                      value={formData.location}
                      onChange={handleChange}
                    >
                      <option value="">Select Location</option>
                      {locations.map(loc => (
                        <option key={loc} value={loc}>{loc}</option>
                      ))}
                    </select>
                    {errors.location && <div className="text-danger small mt-1">{errors.location}</div>}
                  </div>

                  <div className="mb-4">
                    <label className="form-label">
                      <FaCamera className="me-2" /> Upload Images (Optional)
                    </label>
                    <input
                      type="file"
                      className="form-control form-control-lg"
                      accept="image/*"
                      multiple
                      onChange={handleImageUpload}
                    />
                    <small className="text-muted">You can upload multiple images</small>
                    {formData.images.length > 0 && (
                      <div className="mt-2">
                        <strong>Selected: </strong>{formData.images.length} files
                      </div>
                    )}
                  </div>

                  <div className="mb-3">
                    <div className="alert alert-info">
                      <strong>📝 Tip:</strong> Provide detailed information and clear images to help faster resolution.
                    </div>
                  </div>

                  <div className="d-grid gap-2">
                    <button type="submit" className="btn btn-custom btn-lg">
                      <FaPaperPlane className="me-2" /> Submit Issue Report
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default IssueReport;
